        "L0_MLP": "MAPPER",
        "L1_MLP": "COMBINER",
        "L2_MLP": "COMBINER"
    },
    "evidence": {
        "L0_MLP": {
            "hypothesis": "L0_MLP transforms the initial residual stream (single source: token+positional embedding) into a large non-binary output; zeroing it (r3) causes all predictions to collapse to 7, confirming it is a non-binary mapper with one upstream source.",
            "test": "r3",
            "supports": True
        },
        "L1_MLP": {
            "hypothesis": "L1_MLP fuses L0_MLP's output with the token-at-position signal (two sources); when L0_MLP is ablated its write changes by max 138.6; ablating L1_MLP itself (r5) breaks predictions to all-8, confirming its non-binary multi-source output.",
            "test": "r5",
            "supports": True
        },
        "L2_MLP": {
            "hypothesis": "L2_MLP combines L0_MLP and L1_MLP outputs (two+ sources); ablating it (r9) collapses all predictions to 8; ablating L0_MLP or L1_MLP upstream each changes L2_MLP write by 875 and 740 respectively, confirming multiple distinct sources.",
            "test": "r9",
            "supports": True
        }
    }
}

with open('/work/submission.json', 'w') as f:
    json.dump(submission, f, indent=2)
print("Done.")
print(json.dumps(submission, indent=2))

